def get_region_name(region_id: int) -> str:
    for reg in REGIONS:
        if reg["id"] == region_id:
            return reg["name"]
    return "Noma'lum viloyat"

def get_district_name(region_id: int, district_id: int) -> str:
    districts = DISTRICTS.get(region_id, [])
    for d in districts:
        if d["id"] == district_id:
            return d["name"]
    return "Noma'lum tuman"
